import type { HTMLAttributes, Ref } from "react";
import "./Spinner.css";

type SpinnerSize = "small" | "medium" | "large";
type SpinnerTone = "neutral" | "current";

export interface SpinnerProps extends Omit<HTMLAttributes<HTMLSpanElement>, "className"> {
  /**
   * Spinner size.
   *
   * @default "medium"
   */
  size?: SpinnerSize;
  /**
   * Color model. `neutral` = draws a two-tone track + indicator from its own tokens (for neutral
   * surfaces). `current` = monochrome inheriting currentColor — for contexts over a colored fill or
   * where it must follow text color (for example, inside a button). The vocabulary freeze forbids
   * `default` as a name, so this uses `neutral` (the same word as Badge's default variant).
   *
   * @default "neutral"
   */
  tone?: SpinnerTone;
  /** Decorative. When the parent already announces the loading/pending state (for example, a
   *  button's `isPending`), hide it from AT — remove `role="status"` and add `aria-hidden` to
   *  prevent a duplicate announcement. */
  isDecorative?: boolean;
  "aria-label"?: string;
  className?: string;
  ref?: Ref<HTMLSpanElement>;
}

export function Spinner({
  size = "medium",
  tone = "neutral",
  isDecorative = false,
  "aria-label": ariaLabel = "Loading",
  className,
  ...props
}: SpinnerProps) {
  const a11y = isDecorative
    ? { "aria-hidden": true }
    : { role: "status", "aria-label": ariaLabel };
  return (
    <span
      {...props}
      {...a11y}
      data-size={size}
      data-tone={tone}
      className={className ? `sd-spinner ${className}` : "sd-spinner"}
    />
  );
}

.sd-spinner {
  display: inline-block;
  flex: 0 0 auto;
  border: var(--sd-spinner-stroke-width) solid var(--sd-spinner-track);
  border-block-start-color: var(--sd-spinner-indicator);
  border-radius: var(--sd-spinner-radius);
  corner-shape: round;
  animation: sd-spinner-rotate var(--sd-spinner-animation-duration) linear infinite;
}

/* current tone — inherit currentColor (mono) instead of the 2-tone track/indicator, so the
   spinner stays visible on a colored fill and matches the surrounding text (e.g. inside a
   Button). Same ring structure: a translucent track + a solid leading segment. The track can't
   be a colour token here — it has to be mixed from whatever `currentColor` happens to be — so
   the mix ratio is the token instead, which keeps this tone as tunable as the neutral one
   rather than leaving it a hardcoded percentage. */
.sd-spinner[data-tone="current"] {
  border-color: color-mix(
    in srgb,
    currentColor calc(var(--sd-spinner-track-opacity) * 100%),
    transparent
  );
  border-block-start-color: currentColor;
}

.sd-spinner[data-size="small"] {
  width: var(--sd-spinner-size-small);
  height: var(--sd-spinner-size-small);
}

.sd-spinner[data-size="medium"] {
  width: var(--sd-spinner-size-medium);
  height: var(--sd-spinner-size-medium);
}

.sd-spinner[data-size="large"] {
  width: var(--sd-spinner-size-large);
  height: var(--sd-spinner-size-large);
}

@keyframes sd-spinner-rotate {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sd-spinner {
    animation-duration: var(--sd-spinner-animation-duration-reduced);
  }
}
